-- CCN Exam Room: 200-question council-standard mock exam (October 2026)
-- Run this once in the Supabase SQL Editor. It is safe to run again: nothing is added twice.
--
-- What it does:
--   1. Adds the 200 exam questions to the bank as HIDDEN questions (is_active = false), so students
--      cannot see them in the main app before the exam. The Exam Room still uses them.
--   2. Creates the exam "CCN Council Mock Exam — 200 Questions" in the Exam Room with exactly these 200 questions,
--      open 23 Oct 2026 08:00–18:00 (Nigeria time), 200 minutes per student, answers hidden during
--      the exam, score shown at the end. Change the times in the Exam Room admin page if needed —
--      but do NOT press "Pick random questions", or the 200 questions will be replaced.
--
-- Coverage (NMCN CCN curriculum): Section A Applied Sciences (Q1–50), Section B Fundamentals of CCN
-- (Q51–100), Section C Anaesthesia, Emergencies, O&G and Paediatrics (Q101–150), Section D Professional
-- Practice (Q151–200). None are taken from the hospital finals or the Gombe papers.
-- The Word copies (question paper, and answers with explanations) use the same numbering and answers.

insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by v.n),
       v.topic, 'CCN Exam Room Mock — 200 Questions (Oct 2026)', v.q, v.opts, v.ans_idx, v.exp, v.category, v.category_icon, false
from (values
(1, 'Applied Anatomy & Physiology (CCN 410)', 'Surfactant, which lowers surface tension and prevents alveolar collapse, is secreted by:', '["Type II alveolar cells", "Type I alveolar cells", "Alveolar macrophages", "Goblet cells of the bronchi"]'::jsonb, 0, 'Type II pneumocytes make surfactant. Type I cells form the thin gas-exchange surface and macrophages clear debris.', 'Mixed Revision', '📚'),
(2, 'Applied Anatomy & Physiology (CCN 410)', 'The normal resting tidal volume of a healthy adult is about:', '["150 ml", "1,200 ml", "500 ml", "3,000 ml"]'::jsonb, 2, 'Tidal volume is about 500 ml (6–8 ml/kg). About 150 ml of each breath fills the anatomical dead space.', 'Mixed Revision', '📚'),
(3, 'Applied Anatomy & Physiology (CCN 410)', 'In a healthy person, the main chemical stimulus for breathing is:', '["A fall in arterial oxygen (PaO2)", "A rise in arterial carbon dioxide (PaCO2)", "A rise in blood pH", "A fall in body temperature"]'::jsonb, 1, 'Central chemoreceptors respond to CO2 (through H+ in the CSF). Hypoxic drive matters mainly in chronic CO2 retainers.', 'Mixed Revision', '📚'),
(4, 'Applied Anatomy & Physiology (CCN 410)', 'The oxyhaemoglobin dissociation curve shifts to the RIGHT when there is:', '["Fever, a raised PaCO2 and acidosis", "Alkalosis", "Hypothermia", "Low 2,3-DPG"]'::jsonb, 0, 'A right shift (the Bohr effect) means haemoglobin gives up oxygen more easily to the tissues. Alkalosis, cold and low 2,3-DPG shift it to the left.', 'Mixed Revision', '📚'),
(5, 'Applied Anatomy & Physiology (CCN 410)', 'A patient with blood group AB Rhesus positive is known as the:', '["Universal donor", "Universal recipient", "Rhesus-incompatible recipient", "Bombay phenotype"]'::jsonb, 1, 'AB+ has no anti-A, anti-B or anti-D antibodies, so it can receive red cells from any ABO/Rh group. O negative is the universal donor.', 'Mixed Revision', '📚'),
(6, 'Applied Anatomy & Physiology (CCN 410)', 'The normal lifespan of a red blood cell is about:', '["7 days", "30 days", "365 days", "120 days"]'::jsonb, 3, 'Red cells survive about 120 days before being removed by the spleen and liver.', 'Mixed Revision', '📚'),
(7, 'Applied Anatomy & Physiology (CCN 410)', 'Haemophilia A is caused by a deficiency of clotting factor:', '["IX", "XII", "II (prothrombin)", "VIII"]'::jsonb, 3, 'Haemophilia A is factor VIII deficiency. Haemophilia B (Christmas disease) is factor IX deficiency.', 'Mixed Revision', '📚'),
(8, 'Applied Anatomy & Physiology (CCN 410)', 'The normal delay in the cardiac impulse, which allows the ventricles to fill before they contract, occurs at the:', '["Sinoatrial (SA) node", "Atrioventricular (AV) node", "Purkinje fibres", "Bundle of His"]'::jsonb, 1, 'The AV node slows conduction for about 0.1 s so the atria can empty into the ventricles before ventricular systole.', 'Mixed Revision', '📚'),
(9, 'Applied Anatomy & Physiology (CCN 410)', 'The counter-current mechanism that concentrates urine takes place mainly in the:', '["Glomerulus", "Proximal convoluted tubule", "Renal pelvis", "Loop of Henle"]'::jsonb, 3, 'The descending and ascending limbs of the loop of Henle create the medullary concentration gradient, which allows concentrated urine to be formed.', 'Mixed Revision', '📚'),
(10, 'Applied Anatomy & Physiology (CCN 410)', 'The hormone that increases water reabsorption in the collecting ducts is:', '["Aldosterone", "Renin", "Atrial natriuretic peptide", "Antidiuretic hormone (ADH)"]'::jsonb, 3, 'ADH from the posterior pituitary inserts water channels (aquaporins) in the collecting ducts. Aldosterone acts mainly on sodium and potassium.', 'Mixed Revision', '📚'),
(11, 'Applied Anatomy & Physiology (CCN 410)', 'The normal glomerular filtration rate (GFR) of a healthy adult is about:', '["125 ml/min", "25 ml/min", "500 ml/min", "1,200 ml/min"]'::jsonb, 0, 'Normal GFR is about 125 ml/min (180 L/day). About 1,200 ml/min is the renal blood flow.', 'Mixed Revision', '📚'),
(12, 'Applied Anatomy & Physiology (CCN 410)', 'Cerebrospinal fluid (CSF) is mainly produced by the:', '["Choroid plexus of the ventricles", "Arachnoid villi", "Dura mater", "Pineal gland"]'::jsonb, 0, 'The choroid plexuses secrete about 500 ml of CSF a day. The arachnoid villi reabsorb it into the venous sinuses.', 'Mixed Revision', '📚'),
(13, 'Applied Anatomy & Physiology (CCN 410)', 'Constriction of the pupil in response to light is carried out by fibres of which cranial nerve?', '["Trochlear (IV)", "Abducens (VI)", "Oculomotor (III)", "Facial (VII)"]'::jsonb, 2, 'The optic nerve (II) carries the light signal in, and parasympathetic fibres in the oculomotor nerve (III) constrict the pupil. A fixed dilated pupil after head injury suggests compression of III.', 'Mixed Revision', '📚'),
(14, 'Applied Anatomy & Physiology (CCN 410)', 'Insulin is secreted by the:', '["Alpha cells of the islets of Langerhans", "Beta cells of the islets of Langerhans", "Acinar cells of the pancreas", "Delta cells of the islets of Langerhans"]'::jsonb, 1, 'Beta cells make insulin, alpha cells make glucagon and delta cells make somatostatin. Acinar cells make digestive enzymes.', 'Mixed Revision', '📚'),
(15, 'Applied Anatomy & Physiology (CCN 410)', 'Intrinsic factor, needed for the absorption of vitamin B12, is secreted by the:', '["Chief cells of the stomach", "Goblet cells of the colon", "Hepatocytes", "Parietal cells of the stomach"]'::jsonb, 3, 'Parietal cells secrete both hydrochloric acid and intrinsic factor. Without intrinsic factor, B12 is not absorbed in the terminal ileum (pernicious anaemia).', 'Mixed Revision', '📚'),
(16, 'Laboratory Sciences (CCN 426)', 'The normal bicarbonate (HCO3) value on an arterial blood gas is:', '["10 – 14 mmol/L", "22 – 26 mmol/L", "35 – 45 mmol/L", "4 – 8 mmol/L"]'::jsonb, 1, 'HCO3 is the metabolic (kidney-controlled) component. Below 22 suggests metabolic acidosis and above 26 suggests metabolic alkalosis. 35–45 mmHg is the normal PaCO2.', 'ABG & Electrolytes', '🩸'),
(17, 'Laboratory Sciences (CCN 426)', 'An ABG shows pH 7.30, PaCO2 30 mmHg and HCO3 15 mmol/L. The interpretation is:', '["Metabolic acidosis with partial respiratory compensation", "Respiratory acidosis", "Metabolic alkalosis", "Fully compensated respiratory alkalosis"]'::jsonb, 0, 'Low pH with low HCO3 is metabolic acidosis. The low PaCO2 shows the lungs are compensating, but the pH is still abnormal, so compensation is only partial.', 'ABG & Electrolytes', '🩸'),
(18, 'Laboratory Sciences (CCN 426)', 'A ventilated patient whose respiratory rate is set too high has: pH 7.49, PaCO2 27 mmHg, HCO3 23 mmol/L. The interpretation is:', '["Metabolic alkalosis", "Respiratory acidosis", "Uncompensated respiratory alkalosis", "Compensated metabolic acidosis"]'::jsonb, 2, 'High pH with low PaCO2 is respiratory alkalosis (too much CO2 blown off). HCO3 is still normal, so the kidneys have not compensated. Reduce the rate or tidal volume as ordered.', 'ABG & Electrolytes', '🩸'),
(19, 'Laboratory Sciences (CCN 426)', 'Persistent vomiting of gastric contents is most likely to cause:', '["Metabolic acidosis with hyperkalaemia", "Respiratory acidosis", "Respiratory alkalosis with hypernatraemia", "Metabolic alkalosis with hypokalaemia"]'::jsonb, 3, 'Loss of hydrochloric acid raises bicarbonate (metabolic alkalosis), and potassium is lost both in vomit and through the kidneys.', 'ABG & Electrolytes', '🩸'),
(20, 'Laboratory Sciences (CCN 426)', 'Before taking an arterial sample from the radial artery, the modified Allen''s test is done to check:', '["That the ulnar artery can supply the hand", "The patient''s radial pulse rate", "Venous return from the hand", "Capillary refill in the toes"]'::jsonb, 0, 'If the radial artery is injured or clots, the hand depends on the ulnar artery. A positive test (colour returns within about 5–15 s) means ulnar flow is adequate.', 'ABG & Electrolytes', '🩸'),
(21, 'Laboratory Sciences (CCN 426)', 'Within 15 minutes of starting a blood transfusion, a patient develops fever, rigors, loin pain and hypotension. The nurse''s FIRST action is to:', '["Slow the transfusion rate and observe", "Give paracetamol and continue the transfusion", "Flush the line with 5% dextrose", "Stop the transfusion and keep the vein open with normal saline"]'::jsonb, 3, 'These are signs of an acute haemolytic (ABO-incompatible) reaction. Stop the blood at once, keep IV access with a new set and saline, call the doctor and return the bag for checks.', 'ABG & Electrolytes', '🩸'),
(22, 'Laboratory Sciences (CCN 426)', 'Once a unit of blood is taken out of the blood bank fridge, the transfusion should be completed within:', '["12 hours", "24 hours", "4 hours", "48 hours"]'::jsonb, 2, 'Start within 30 minutes of removal and finish within 4 hours, to limit the risk of bacterial growth.', 'ABG & Electrolytes', '🩸'),
(23, 'Laboratory Sciences (CCN 426)', 'The main measures in managing a vaso-occlusive sickle cell crisis are:', '["Fluid restriction and cold compresses", "Oral iron and a high-protein diet", "Diuretics and bed rest only", "Hydration, oxygen, adequate pain relief and treating infection"]'::jsonb, 3, 'Dehydration, hypoxia, infection and cold all increase sickling. Fluids, oxygen and strong analgesia (often opioids) are the core treatment. Cold causes vasoconstriction.', 'ABG & Electrolytes', '🩸'),
(24, 'Laboratory Sciences (CCN 426)', 'Which set of laboratory results is typical of disseminated intravascular coagulation (DIC)?', '["High platelets, short PT and raised fibrinogen", "Low platelets, prolonged PT/APTT, low fibrinogen and raised D-dimer", "Normal clotting with a low D-dimer", "Raised haemoglobin with normal platelets"]'::jsonb, 1, 'In DIC, clotting factors and platelets are used up while clots are broken down, so fibrinogen falls and fibrin degradation products (D-dimer) rise.', 'ABG & Electrolytes', '🩸'),
(25, 'Laboratory Sciences (CCN 426)', 'Which organism is well known for multidrug resistance and for causing ventilator-associated pneumonia in the ICU?', '["Streptococcus pyogenes", "Clostridium tetani", "Pseudomonas aeruginosa", "Treponema pallidum"]'::jsonb, 2, 'Pseudomonas and other Gram-negative bacteria (Acinetobacter, Klebsiella) are common, resistant causes of VAP and other ICU infections.', 'ABG & Electrolytes', '🩸'),
(26, 'Laboratory Sciences (CCN 426)', 'Sterilisation using steam under pressure (about 121°C for 15 minutes) is called:', '["Boiling", "Autoclaving", "Pasteurisation", "Chemical disinfection"]'::jsonb, 1, 'The autoclave kills all organisms, including spores. Boiling and most chemical disinfectants do not reliably kill spores.', 'ABG & Electrolytes', '🩸'),
(27, 'Laboratory Sciences (CCN 426)', 'Blood cultures in a patient with suspected sepsis should ideally be taken:', '["After the first dose of antibiotics", "After 3 days of antibiotics", "Before the first dose of antibiotics", "From the IV line the drip is running through"]'::jsonb, 2, 'Antibiotics can sterilise the sample and give a false negative. Take two sets aseptically from fresh venepuncture sites, but do not delay antibiotics for long.', 'ABG & Electrolytes', '🩸'),
(28, 'Applied Pharmacology (CCN 414)', 'The adult dose of adrenaline for anaphylaxis is:', '["1 mg of 1:1,000 as a rapid IV bolus", "5 mg subcutaneously", "0.5 mg IM (0.5 ml of 1:1,000) into the anterolateral thigh", "0.05 mg orally"]'::jsonb, 2, 'IM adrenaline 0.5 mg, repeated after 5 minutes if needed, is first-line. Undiluted 1:1,000 must never be given as an IV bolus.', 'ICU Pharmacology', '💊'),
(29, 'Applied Pharmacology (CCN 414)', 'The antidote for heparin overdose is:', '["Protamine sulphate", "Vitamin K", "Naloxone", "Flumazenil"]'::jsonb, 0, 'Protamine neutralises heparin. Vitamin K reverses warfarin.', 'ICU Pharmacology', '💊'),
(30, 'Applied Pharmacology (CCN 414)', 'The specific antidote for benzodiazepine overdose is:', '["Naloxone", "Atropine", "N-acetylcysteine", "Flumazenil"]'::jsonb, 3, 'Flumazenil blocks benzodiazepine receptors. Naloxone reverses opioids and N-acetylcysteine treats paracetamol poisoning.', 'ICU Pharmacology', '💊'),
(31, 'Applied Pharmacology (CCN 414)', 'A farmer is brought in with pinpoint pupils, heavy salivation, sweating, diarrhoea and bradycardia after spraying insecticide. The drug of choice is:', '["Naloxone", "Desferrioxamine", "Protamine sulphate", "Atropine"]'::jsonb, 3, 'These are cholinergic (SLUDGE) features of organophosphate poisoning. Atropine is given until secretions dry, with pralidoxime where available.', 'ICU Pharmacology', '💊'),
(32, 'Applied Pharmacology (CCN 414)', 'A patient on a sodium nitroprusside infusion should be monitored for toxicity from:', '["Cyanide (thiocyanate)", "Lithium", "Digoxin", "Potassium"]'::jsonb, 0, 'Nitroprusside breaks down to cyanide. The infusion must be protected from light and its rate and duration limited.', 'ICU Pharmacology', '💊'),
(33, 'Applied Pharmacology (CCN 414)', 'Glyceryl trinitrate (GTN) relieves angina mainly by:', '["Increasing the heart rate", "Dilating veins, which reduces preload and myocardial oxygen demand", "Constricting the coronary arteries", "Increasing afterload"]'::jsonb, 1, 'Nitrates are mainly venodilators. Lower preload reduces the heart''s workload. Watch for hypotension and headache.', 'ICU Pharmacology', '💊'),
(34, 'Applied Pharmacology (CCN 414)', 'Which of these drugs is a mucolytic used to loosen thick secretions?', '["Salbutamol", "Ipratropium bromide", "Furosemide", "N-acetylcysteine"]'::jsonb, 3, 'N-acetylcysteine breaks the disulphide bonds in mucus. Salbutamol and ipratropium are bronchodilators.', 'ICU Pharmacology', '💊'),
(35, 'Applied Pharmacology (CCN 414)', 'Suxamethonium, a depolarising muscle relaxant, can cause:', '["Hypoglycaemia and hypothermia", "Hyperkalaemia and malignant hyperthermia", "Hypercalcaemia and seizures", "Thrombocytopenia and bleeding"]'::jsonb, 1, 'Suxamethonium releases potassium from muscle (dangerous in burns, crush injury and renal failure) and can trigger malignant hyperthermia.', 'ICU Pharmacology', '💊'),
(36, 'Applied Pharmacology (CCN 414)', 'When a ventilated patient is sedated with a propofol infusion, the nurse must watch mainly for:', '["Hypertension and tachypnoea", "Hyperglycaemia only", "Polyuria", "Hypotension and respiratory depression"]'::jsonb, 3, 'Propofol causes vasodilation and depresses the myocardium and breathing. Prolonged high doses can also cause propofol infusion syndrome and raised triglycerides.', 'ICU Pharmacology', '💊'),
(37, 'Applied Pharmacology (CCN 414)', 'The most important side effect of IV morphine for the critical care nurse to monitor is:', '["Diarrhoea", "Respiratory depression", "Hypertension", "Hyperglycaemia"]'::jsonb, 1, 'Opioids depress the respiratory centre, so monitor respiratory rate, sedation score and SpO2. Naloxone reverses it.', 'ICU Pharmacology', '💊'),
(38, 'Applied Pharmacology (CCN 414)', 'Dopamine 400 mg is diluted in 250 ml. The order is 5 mcg/kg/min for an 80 kg patient. The pump rate is:', '["24 ml/hour", "15 ml/hour", "30 ml/hour", "6 ml/hour"]'::jsonb, 1, 'Concentration = 400,000 mcg ÷ 250 ml = 1,600 mcg/ml. Dose = 5 × 80 = 400 mcg/min = 24,000 mcg/hour. Rate = 24,000 ÷ 1,600 = 15 ml/hour.', 'ICU Pharmacology', '💊'),
(39, 'Applied Pharmacology (CCN 414)', 'One litre of normal saline is to run over 8 hours through a giving set that delivers 20 drops/ml. The drip rate is about:', '["42 drops/minute", "21 drops/minute", "63 drops/minute", "125 drops/minute"]'::jsonb, 0, 'Drops/min = (volume × drop factor) ÷ minutes = (1,000 × 20) ÷ 480 = 41.7, so about 42 drops/min.', 'ICU Pharmacology', '💊'),
(40, 'Applied Pharmacology (CCN 414)', 'Activated charcoal is contraindicated in poisoning with:', '["Paracetamol taken within 1 hour", "Corrosives (acids or alkalis) and hydrocarbons such as kerosene", "Phenobarbital", "Carbamazepine"]'::jsonb, 1, 'Charcoal does not bind corrosives or hydrocarbons, and it raises the risk of aspiration. It also blocks the view at endoscopy after corrosive injury.', 'ICU Pharmacology', '💊'),
(41, 'Radiology (CCN 427)', 'On an erect chest X-ray, a haemothorax typically shows:', '["A hyperlucent area with no lung markings", "An air bronchogram only", "Blunting of the costophrenic angle with a fluid meniscus", "A widened intercostal space with no other change"]'::jsonb, 2, 'Blood collects at the base, giving a meniscus-shaped opacity. A large haemothorax gives a ''white-out''.', 'Mixed Revision', '📚'),
(42, 'Radiology (CCN 427)', 'The X-ray sign of a pneumothorax is:', '["A visible visceral pleural line with no lung markings beyond it", "Kerley B lines", "A ''bat-wing'' perihilar shadow", "A fluid meniscus at the base"]'::jsonb, 0, 'Air in the pleural space separates the lung edge from the chest wall, leaving a dark area with no vessels. Kerley B lines and bat-wing shadows suggest pulmonary oedema.', 'Mixed Revision', '📚'),
(43, 'Radiology (CCN 427)', 'An erect abdominal X-ray in intestinal obstruction typically shows:', '["Free gas under the diaphragm", "Calcified gallstones", "Dilated bowel loops with multiple air–fluid levels", "A normal gas pattern"]'::jsonb, 2, 'Fluid and gas build up above the blockage, forming step-ladder air–fluid levels. Gas under the diaphragm means perforation.', 'Mixed Revision', '📚'),
(44, 'Radiology (CCN 427)', 'Before an intravenous urogram (IVU/IVP) with iodinated contrast, the nurse should check for:', '["Allergy to contrast/iodine and the patient''s renal function", "Blood group and cross-match", "Visual acuity", "Hearing"]'::jsonb, 0, 'Iodinated contrast can cause allergic reactions and contrast-induced kidney injury, so ask about previous reactions, asthma and metformin, and check creatinine.', 'Mixed Revision', '📚'),
(45, 'Radiology (CCN 427)', 'Kerley B lines and bilateral ''bat-wing'' perihilar shadowing on a chest X-ray suggest:', '["Pneumothorax", "Rib fracture", "Pulmonary oedema", "Lobar collapse"]'::jsonb, 2, 'Fluid in the interstitium and alveoli produces these signs, often with cardiomegaly and upper-lobe venous diversion in heart failure.', 'Mixed Revision', '📚'),
(46, 'Computer & ICT in Critical Care Nursing', 'The part of the processor that performs calculations and logical comparisons is the:', '["Control Unit", "Read Only Memory (ROM)", "Video display unit", "Arithmetic Logic Unit (ALU)"]'::jsonb, 3, 'The CPU has a control unit, which directs operations, and an ALU, which does arithmetic and logic such as comparing a reading with an alarm limit.', 'Research & Nursing Process', '📊'),
(47, 'Computer & ICT in Critical Care Nursing', 'Computer memory that loses its contents when the power is switched off is:', '["Random Access Memory (RAM)", "Read Only Memory (ROM)", "Hard disk", "USB flash drive"]'::jsonb, 0, 'RAM is volatile working memory. ROM, hard disks and flash drives keep their data without power.', 'Research & Nursing Process', '📊'),
(48, 'Computer & ICT in Critical Care Nursing', 'A major benefit of the computer-based (electronic) patient record in the ICU is:', '["It removes the need for patient confidentiality", "It allows anyone to change entries without a trace", "Quick access to legible, complete patient data by authorised staff", "It replaces the need for nursing assessment"]'::jsonb, 2, 'Electronic records improve legibility, speed and continuity of care. Access is protected by passwords and audit trails, so confidentiality still applies.', 'Research & Nursing Process', '📊'),
(49, 'Computer & ICT in Critical Care Nursing', 'Telemedicine is best defined as:', '["Treating patients only by telephone calls between nurses", "Television programmes about health", "Using robots to replace nurses", "Delivering health care and expert advice at a distance using information and communication technology"]'::jsonb, 3, 'Telemedicine connects patients and remote specialists through video, data transfer and remote monitoring.', 'Research & Nursing Process', '📊'),
(50, 'Computer & ICT in Critical Care Nursing', 'In ICT classification, a pulse oximeter and a cardiac monitor are examples of:', '["Treatment devices", "Storage devices", "Monitoring devices", "Input devices for a computer"]'::jsonb, 2, 'The curriculum groups devices into diagnostic (ultrasound, CT), monitoring (oximeter, cardiac monitor) and treatment (radiotherapy, physiotherapy equipment).', 'Research & Nursing Process', '📊'),
(51, 'Pulmonary & Respiratory Disorders (CCN 412)', 'A patient with acute cardiogenic pulmonary oedema is breathless and coughing pink frothy sputum. The best position is:', '["Upright, sitting up with the legs down", "Flat on the back", "Head-down (Trendelenburg)", "Prone"]'::jsonb, 0, 'Sitting upright with the legs dependent reduces venous return (preload) and helps the diaphragm, which eases breathing.', 'Respiratory', '🫁'),
(52, 'Pulmonary & Respiratory Disorders (CCN 412)', 'The IV drug commonly given in acute pulmonary oedema to remove excess fluid is:', '["Propranolol", "Furosemide", "5% dextrose bolus", "Normal saline bolus"]'::jsonb, 1, 'Furosemide, a loop diuretic, causes rapid diuresis and venodilation. Fluid boluses and beta-blockers would worsen acute pulmonary oedema.', 'Respiratory', '🫁'),
(53, 'Pulmonary & Respiratory Disorders (CCN 412)', 'On the third day after hip surgery, a patient on bed rest suddenly develops breathlessness, pleuritic chest pain, tachycardia and anxiety. The most likely diagnosis is:', '["Acute asthma", "Lobar pneumonia", "Pericarditis", "Pulmonary embolism"]'::jsonb, 3, 'Immobility after surgery causes DVT, which can travel to the lungs. A sudden onset with tachycardia and tachypnoea is typical of PE.', 'Respiratory', '🫁'),
(54, 'Pulmonary & Respiratory Disorders (CCN 412)', 'The preferred investigation to confirm a pulmonary embolism is:', '["Plain chest X-ray", "CT pulmonary angiography (CTPA)", "Sputum culture", "Peak flow measurement"]'::jsonb, 1, 'CTPA shows clot in the pulmonary arteries. The chest X-ray and ECG are often normal or non-specific in PE.', 'Respiratory', '🫁'),
(55, 'Pulmonary & Respiratory Disorders (CCN 412)', 'A thin COPD patient who breathes through pursed lips, has a barrel chest and is not cyanosed (a ''pink puffer'') most likely has:', '["Chronic bronchitis", "Emphysema", "Bronchiectasis", "Asthma"]'::jsonb, 1, 'In emphysema, alveolar walls are destroyed and the patient hyperventilates to keep oxygenation (''pink puffer''). Chronic bronchitis gives the cyanosed, oedematous ''blue bloater''.', 'Respiratory', '🫁'),
(56, 'Pulmonary & Respiratory Disorders (CCN 412)', 'For a COPD patient with chronic CO2 retention, oxygen should be given:', '["At 100% by non-rebreather mask, aiming for SpO2 100%", "Not at all, because oxygen is dangerous in COPD", "Controlled, at 24–28% by Venturi mask, aiming for SpO2 88–92%", "At 15 L/min by nasal cannula"]'::jsonb, 2, 'Too much oxygen can worsen hypercapnia (V/Q mismatch, loss of hypoxic drive). Hypoxia kills, so oxygen is never withheld; it is given in a controlled way.', 'Respiratory', '🫁'),
(57, 'Pulmonary & Respiratory Disorders (CCN 412)', 'In a trauma patient with suspected tension pneumothorax, the correct action is:', '["Immediate needle decompression, without waiting for a chest X-ray", "Send for a chest X-ray to confirm first", "Give a nebulised bronchodilator", "Insert a nasogastric tube"]'::jsonb, 0, 'Tension pneumothorax is a clinical diagnosis and can kill within minutes. Decompress at once, then insert a chest drain.', 'Respiratory', '🫁'),
(58, 'Pulmonary & Respiratory Disorders (CCN 412)', 'The usual site for chest drain insertion in a haemothorax (the ''safe triangle'') is the:', '["2nd intercostal space, mid-clavicular line", "8th intercostal space, posterior", "5th intercostal space, just in front of the mid-axillary line", "3rd intercostal space, beside the sternum"]'::jsonb, 2, 'The safe triangle is bordered by the lateral edge of pectoralis major, the lateral edge of latissimus dorsi and the 5th intercostal space. This avoids major vessels and organs.', 'Respiratory', '🫁'),
(59, 'Pulmonary & Respiratory Disorders (CCN 412)', 'Type 2 (hypercapnic) respiratory failure is defined as:', '["PaO2 below 60 mmHg with a normal or low PaCO2", "A normal PaO2 with a low PaCO2", "SpO2 above 95% on room air", "PaO2 below 60 mmHg (8 kPa) with PaCO2 above 50 mmHg (6.5 kPa)"]'::jsonb, 3, 'Type 1 is hypoxaemia alone (failure of oxygenation). Type 2 adds CO2 retention (failure of ventilation), as in COPD, drug overdose or neuromuscular disease.', 'Respiratory', '🫁'),
(60, 'Pulmonary & Respiratory Disorders (CCN 412)', 'The main benefit of BiPAP in an acute exacerbation of COPD is that it:', '["Reduces the work of breathing and clears CO2 without the need for intubation", "Cures the underlying lung disease", "Replaces the need for oxygen", "Is safe in an unconscious patient who cannot protect the airway"]'::jsonb, 0, 'Non-invasive ventilation supports breathing through a mask, lowers PaCO2 and avoids the complications of an endotracheal tube. It needs a conscious, cooperative patient.', 'Respiratory', '🫁'),
(61, 'Pulmonary & Respiratory Disorders (CCN 412)', 'Using the Berlin definition, SEVERE ARDS has a PaO2/FiO2 ratio of:', '["300 mmHg or less", "400 mmHg or less", "500 mmHg or less", "100 mmHg or less"]'::jsonb, 3, 'With PEEP of at least 5 cmH2O: mild is 201–300, moderate is 101–200 and severe is 100 or less.', 'Respiratory', '🫁'),
(62, 'Pulmonary & Respiratory Disorders (CCN 412)', 'The recommended ventilation strategy for ARDS is:', '["High tidal volume of 12–15 ml/kg", "Zero PEEP", "Plateau pressure above 40 cmH2O", "Low tidal volume (about 6 ml/kg of predicted body weight) with plateau pressure below 30 cmH2O"]'::jsonb, 3, 'Lung-protective ventilation limits volutrauma and barotrauma and lowers mortality. Adequate PEEP keeps the alveoli open.', 'Respiratory', '🫁'),
(63, 'Pulmonary & Respiratory Disorders (CCN 412)', 'Rapid correction of chronic hyponatraemia can cause:', '["Cerebral haemorrhage", "Osmotic demyelination syndrome (central pontine myelinolysis)", "Hypokalaemia", "Renal stones"]'::jsonb, 1, 'Sodium should rise by no more than about 8–10 mmol/L in 24 hours. Rapid shifts of water out of brain cells damage myelin in the pons.', 'Respiratory', '🫁'),
(64, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'Afterload of the left ventricle is mainly determined by:', '["Systemic vascular resistance", "Venous return", "Total blood volume", "Right atrial pressure"]'::jsonb, 0, 'Afterload is the resistance the ventricle pumps against. Preload is the end-diastolic stretch, which depends on venous return.', 'Cardiovascular', '🫀'),
(65, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'Chest pain that comes on during exercise, is relieved by rest and GTN within minutes, and causes no rise in troponin is:', '["Acute myocardial infarction", "Pericarditis", "Stable angina", "Aortic dissection"]'::jsonb, 2, 'Stable angina is reversible ischaemia. Pain at rest, pain lasting more than 20 minutes, or a troponin rise suggests acute coronary syndrome.', 'Cardiovascular', '🫀'),
(66, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'The most specific blood marker of myocardial damage is:', '["Cardiac troponin (I or T)", "Total creatine kinase", "Lactate dehydrogenase", "Aspartate aminotransferase"]'::jsonb, 0, 'Troponins are specific to heart muscle. They rise within 3–6 hours and stay raised for up to 2 weeks.', 'Cardiovascular', '🫀'),
(67, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'The initial management of a patient with acute STEMI includes:', '["Early ambulation and a bed bath", "Aspirin 300 mg chewed, oxygen if SpO2 is below 94%, nitrates, pain relief and urgent reperfusion", "IV fluids at 2 L/hour", "Withholding all analgesia until the ECG normalises"]'::jsonb, 1, 'Antiplatelets, pain control and rapid reperfusion (PCI or thrombolysis) limit infarct size. Oxygen is given only when the patient is hypoxic.', 'Cardiovascular', '🫀'),
(68, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'Which of these is a sign of LEFT-sided heart failure?', '["Orthopnoea with bilateral basal crackles", "Ascites", "Dependent pitting pedal oedema", "Hepatomegaly"]'::jsonb, 0, 'When the left ventricle fails, blood backs up into the lungs. Right-sided failure causes systemic congestion: raised JVP, liver enlargement, ascites and ankle oedema.', 'Cardiovascular', '🫀'),
(69, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'A patient with mitral stenosis is expected to have:', '["A mid-diastolic rumbling murmur at the apex", "A pansystolic murmur at the apex", "An ejection systolic murmur at the aortic area", "A continuous ''machinery'' murmur"]'::jsonb, 0, 'Blood flowing through a narrowed mitral valve during ventricular filling (diastole) gives a low-pitched rumble. Mitral regurgitation gives a pansystolic murmur.', 'Cardiovascular', '🫀'),
(70, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'On an ECG, a PR interval that gets longer with each beat until a QRS complex is dropped is:', '["First-degree heart block", "Mobitz type II block", "Third-degree (complete) heart block", "Second-degree heart block, Mobitz type I (Wenckebach)"]'::jsonb, 3, 'Mobitz I is usually benign and at the AV node. Mobitz II drops beats without warning (fixed PR) and can progress to complete block.', 'Cardiovascular', '🫀'),
(71, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'On the monitor of a patient with a temporary pacemaker, ''failure to capture'' appears as:', '["QRS complexes with no pacing spikes", "A heart rate faster than the set rate", "A pacing spike falling on the T wave", "Pacing spikes that are not followed by a QRS complex"]'::jsonb, 3, 'The pacemaker fires but the myocardium does not respond. Check the connections and lead position, and increase the output (mA) as ordered.', 'Cardiovascular', '🫀'),
(72, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'After an intra-aortic balloon pump is inserted through the femoral artery, a weak LEFT radial pulse suggests:', '["The balloon is working perfectly", "The patient is fluid overloaded", "The balloon has moved up and is blocking the left subclavian artery", "The right leg is ischaemic"]'::jsonb, 2, 'The balloon tip should sit 1–2 cm below the left subclavian artery. Also check the leg on the insertion side for distal pulses and perfusion.', 'Cardiovascular', '🫀'),
(73, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'The pulmonary artery wedge pressure (PAWP) measured with a Swan-Ganz catheter reflects pressure in the:', '["Left atrium (left ventricular end-diastolic pressure)", "Right atrium", "Right ventricle during systole", "Systemic arteries"]'::jsonb, 0, 'With the balloon wedged, the catheter ''sees'' through the pulmonary capillaries to the left atrium. Normal PAWP is about 6–12 mmHg.', 'Cardiovascular', '🫀'),
(74, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'The vasopressor of first choice in septic shock is:', '["Dobutamine", "Isoprenaline", "Noradrenaline", "Low-dose dopamine"]'::jsonb, 2, 'Noradrenaline (mainly an alpha-agonist) raises SVR and MAP, with a target MAP of 65 mmHg or more. Dobutamine mainly increases contractility (beta-1).', 'Cardiovascular', '🫀'),
(75, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'In haemorrhagic shock, systolic blood pressure usually first falls at which class of blood loss?', '["Class I (up to 15%)", "Class III (30–40% blood loss)", "Class II (15–30%)", "Systolic pressure never falls in haemorrhage"]'::jsonb, 1, 'In classes I and II the body compensates with tachycardia and vasoconstriction. Falling BP is a late sign that appears at class III.', 'Cardiovascular', '🫀'),
(76, 'Cardiac Disorders & Haemodynamics (CCN 412)', 'The earliest reliable sign of hypovolaemic shock is usually:', '["Hypotension", "Tachycardia", "Bradycardia", "Fixed dilated pupils"]'::jsonb, 1, 'The heart rate rises to keep cardiac output up. Hypotension appears only after about 30% of blood volume is lost.', 'Cardiovascular', '🫀'),
(77, 'Renal Disorders (CCN 412)', 'The most common cause of pre-renal acute kidney injury is:', '["Hypovolaemia from haemorrhage or dehydration", "Nephrotoxic drugs", "Enlarged prostate", "Glomerulonephritis"]'::jsonb, 0, 'Pre-renal AKI is caused by poor kidney perfusion. Drugs and glomerulonephritis cause intrinsic (renal) AKI, and prostate obstruction causes post-renal AKI.', 'Renal & Fluid Balance', '💧'),
(78, 'Renal Disorders (CCN 412)', 'The most useful routine blood test of kidney function is:', '["Serum ALT", "Serum amylase", "Serum creatinine with eGFR", "Serum bilirubin"]'::jsonb, 2, 'Creatinine is cleared by glomerular filtration. eGFR, calculated from creatinine, stages kidney disease.', 'Renal & Fluid Balance', '💧'),
(79, 'Renal Disorders (CCN 412)', 'A patient has serum potassium of 7.2 mmol/L and peaked T waves on the ECG. The FIRST drug given to protect the heart is:', '["IV calcium gluconate 10%", "IV potassium chloride", "Oral furosemide", "IV normal saline only"]'::jsonb, 0, 'Calcium stabilises the myocardial membrane within minutes. Insulin–dextrose and salbutamol then shift potassium into cells, and potassium is finally removed by dialysis or binders.', 'Renal & Fluid Balance', '💧'),
(80, 'Renal Disorders (CCN 412)', 'Correct care of an arteriovenous (AV) fistula for haemodialysis includes:', '["Taking blood pressure on the fistula arm", "Feeling for a thrill and listening for a bruit every day", "Applying a tight bandage over the fistula", "Using the fistula arm for routine IV cannulation"]'::jsonb, 1, 'A thrill and bruit show the fistula is patent. Avoid BP cuffs, needles and pressure on that arm.', 'Renal & Fluid Balance', '💧'),
(81, 'Renal Disorders (CCN 412)', 'During a patient''s first haemodialysis session, they develop headache, nausea, restlessness and then a seizure. The most likely cause is:', '["Dialysis disequilibrium syndrome", "Air embolism", "Hypokalaemia", "Hepatic encephalopathy"]'::jsonb, 0, 'Rapid removal of urea from the blood creates an osmotic gradient that causes cerebral oedema. Early sessions should be short and gentle.', 'Renal & Fluid Balance', '💧'),
(82, 'Renal Disorders (CCN 412)', 'A common complication of continuous renal replacement therapy (CRRT) is:', '["Hyperthermia", "Polycythaemia", "Hypernatraemia in every case", "Hypothermia from heat loss in the extracorporeal circuit"]'::jsonb, 3, 'Large volumes of blood and fluid outside the body cool the patient. Other complications include bleeding from anticoagulation, filter clotting and electrolyte imbalance.', 'Renal & Fluid Balance', '💧'),
(83, 'Neurology (CCN 412)', 'A head-injured patient opens the eyes to pain, makes incomprehensible sounds and withdraws from pain. The Glasgow Coma Scale score is:', '["7", "8", "9", "10"]'::jsonb, 1, 'Eyes to pain = 2, incomprehensible sounds = 2, withdraws from pain = 4. Total 8, which is severe head injury.', 'Neurology', '🧠'),
(84, 'Neurology (CCN 412)', 'A GCS of 8 or below in a head-injured patient indicates:', '["Mild head injury", "Moderate head injury", "Confirmed brain death", "Severe head injury; the airway must be secured"]'::jsonb, 3, 'GCS 13–15 is mild, 9–12 moderate and 3–8 severe. ''Eight, intubate'': such patients cannot protect their airway.', 'Neurology', '🧠'),
(85, 'Neurology (CCN 412)', 'After a blow to the temple, a patient briefly loses consciousness, recovers fully, then deteriorates rapidly hours later. The most likely diagnosis is:', '["Chronic subdural haematoma", "Concussion only", "Extradural (epidural) haematoma", "Subarachnoid haemorrhage from a berry aneurysm"]'::jsonb, 2, 'A torn middle meningeal artery bleeds quickly after a ''lucid interval''. Urgent surgical evacuation is needed. Subdural haematomas come from torn bridging veins.', 'Neurology', '🧠'),
(86, 'Neurology (CCN 412)', 'Cushing''s triad, a late sign of raised intracranial pressure, consists of:', '["Hypotension, tachycardia and fast breathing", "Fever, neck stiffness and rash", "Hypertension with a widening pulse pressure, bradycardia and irregular breathing", "Tachycardia, sweating and tremor"]'::jsonb, 2, 'Brainstem compression triggers this reflex. It warns of impending herniation.', 'Neurology', '🧠'),
(87, 'Neurology (CCN 412)', 'The Monro-Kellie doctrine states that:', '["The brain can expand freely within the skull", "CSF volume never changes", "Intracranial pressure does not depend on blood volume", "The skull has a fixed volume, so an increase in brain, blood or CSF must be offset by a decrease in the others"]'::jsonb, 3, 'When compensation (CSF and venous blood displacement) is used up, ICP rises steeply.', 'Neurology', '🧠'),
(88, 'Neurology (CCN 412)', 'A nursing measure to reduce raised intracranial pressure is to:', '["Lie the patient flat with the head turned to one side", "Use a head-down tilt", "Tie the ETT tapes tightly around the neck", "Raise the head of the bed to 30° with the neck in a neutral position"]'::jsonb, 3, 'These positions help cerebral venous drainage. Also avoid hip flexion, hypercapnia, coughing and straining, and space out nursing care.', 'Neurology', '🧠'),
(89, 'Neurology (CCN 412)', 'A positive Babinski sign in an adult shows:', '["A lower motor neuron lesion", "A normal adult response", "An upper motor neuron lesion", "Peripheral neuropathy"]'::jsonb, 2, 'Stroking the sole makes the big toe extend upward and the other toes fan out. This is normal only in infants.', 'Neurology', '🧠'),
(90, 'Neurology (CCN 412)', 'A LICOX catheter in neurocritical care measures:', '["Serum sodium", "Brain tissue oxygen tension (PbtO2) and temperature", "Electrical activity of the brain (EEG)", "CSF glucose"]'::jsonb, 1, 'PbtO2 below about 20 mmHg suggests cerebral hypoxia, which guides treatment after severe brain injury.', 'Neurology', '🧠'),
(91, 'Neurology (CCN 412)', 'Brain death is confirmed when there is:', '["Absence of spinal reflexes in the legs", "A GCS of 8", "Absence of all brainstem reflexes and no breathing on apnoea testing, with reversible causes excluded", "Fixed pupils only, after a sedative overdose"]'::jsonb, 2, 'Hypothermia, sedatives, metabolic and endocrine causes must be excluded first. Spinal reflexes can persist in brain death.', 'Neurology', '🧠'),
(92, 'Neurology (CCN 412)', 'Passive flexion of the neck causing involuntary flexion of the hips and knees is:', '["Kernig''s sign", "Babinski''s sign", "Brudzinski''s sign", "Chvostek''s sign"]'::jsonb, 2, 'Brudzinski''s and Kernig''s signs (pain and resistance on extending the knee with the hip flexed) are meningeal signs seen in meningitis and subarachnoid haemorrhage.', 'Neurology', '🧠'),
(93, 'Neurology (CCN 412)', 'In Guillain-Barré syndrome, the most important nursing assessment is:', '["Blood glucose", "Visual acuity", "Bowel sounds", "Respiratory function, especially vital capacity"]'::jsonb, 3, 'GBS causes ascending, symmetrical flaccid paralysis that can reach the respiratory muscles. A falling vital capacity (below about 15–20 ml/kg) signals the need for ventilation.', 'Neurology', '🧠'),
(94, 'Neurology (CCN 412)', 'Myasthenia gravis is caused by:', '["Demyelination of peripheral nerves", "Antibodies against acetylcholine receptors at the neuromuscular junction", "Degeneration of dopamine neurons", "Tetanus toxin"]'::jsonb, 1, 'Muscle weakness worsens with activity. A myasthenic crisis (too little drug) or a cholinergic crisis (too much drug) can cause respiratory failure.', 'Neurology', '🧠'),
(95, 'Neurology (CCN 412)', 'A patient with tetanus should be nursed:', '["In a bright, busy area near the nurses'' station for observation", "In a quiet, dim room with care grouped together to reduce stimulation", "With frequent turning every 15 minutes", "With visitors encouraged to stimulate the patient"]'::jsonb, 1, 'Noise, light and touch trigger painful spasms and laryngospasm. Sedation, muscle relaxants, antitoxin and wound care are also needed.', 'Neurology', '🧠'),
(96, 'Neurology (CCN 412)', 'The first-line drug for a patient in status epilepticus is:', '["Oral phenytoin", "Paracetamol", "An IV benzodiazepine such as lorazepam or diazepam", "IV potassium chloride"]'::jsonb, 2, 'Benzodiazepines are given first (buccal or rectal if there is no IV access), followed by phenytoin, levetiracetam or valproate if seizures continue.', 'Neurology', '🧠'),
(97, 'Delirium & TENS in the ICU (CCN 412)', 'The standard bedside tool for assessing delirium in a mechanically ventilated patient is:', '["Glasgow Coma Scale", "CAM-ICU (Confusion Assessment Method for the ICU)", "Braden scale", "APGAR score"]'::jsonb, 1, 'CAM-ICU checks for acute onset or fluctuating course, inattention, and disorganised thinking or altered consciousness. It can be used in patients who cannot speak.', 'Neurology', '🧠'),
(98, 'Delirium & TENS in the ICU (CCN 412)', 'Which of these is a NON-pharmacological measure to prevent delirium in the ICU?', '["Reorientation, glasses and hearing aids, early mobilisation and protecting night-time sleep", "Keeping lights on and noise high at night", "Routine physical restraints", "Deep sedation for every patient"]'::jsonb, 0, 'Delirium bundles focus on sleep, orientation, mobility, sensory aids and less sedation. Restraints and benzodiazepines increase delirium.', 'Neurology', '🧠'),
(99, 'Delirium & TENS in the ICU (CCN 412)', 'Toxic epidermal necrolysis (TEN) is most commonly triggered by:', '["Sunburn", "Drugs such as sulphonamides, carbamazepine, allopurinol and nevirapine", "Viral warts", "Contact with water"]'::jsonb, 1, 'TEN is a severe drug reaction. The first step is to stop the offending drug.', 'Neurology', '🧠'),
(100, 'Delirium & TENS in the ICU (CCN 412)', 'Toxic epidermal necrolysis involves epidermal detachment of:', '["Less than 10% of body surface area only", "The scalp only", "The mucous membranes only, never the skin", "More than 30% of body surface area, and is managed like a major burn"]'::jsonb, 3, 'Below 10% is Stevens-Johnson syndrome, 10–30% is overlap, and above 30% is TEN. Care focuses on fluids, wound care, temperature control, infection prevention and eye and mouth care.', 'Neurology', '🧠'),
(101, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'A HIGH-pressure alarm on a volume-controlled ventilator is commonly caused by:', '["Disconnection of the circuit", "A leak around the cuff", "A ruptured humidifier chamber", "Secretions, a kinked tube or the patient biting the tube"]'::jsonb, 3, 'Anything that raises airway resistance or lowers compliance raises pressure. Disconnection and cuff leaks cause LOW-pressure alarms.', 'Respiratory', '🫁'),
(102, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'In an intubated patient, the capnography (ETCO2) waveform suddenly drops to zero. The most likely cause is:', '["Fever", "Disconnection, dislodged tube or oesophageal intubation", "Mild hyperventilation", "Normal sleep"]'::jsonb, 1, 'No CO2 detected means no gas exchange is reaching the sensor. Check the patient and tube at once. Normal ETCO2 is 35–45 mmHg.', 'Respiratory', '🫁'),
(103, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'When intubating a patient with suspected cervical spine injury, the nurse should:', '["Hyperextend the neck for a better view", "Use a head-tilt chin-lift", "Keep manual in-line stabilisation of the neck", "Remove the collar and leave the neck unsupported"]'::jsonb, 2, 'In-line stabilisation prevents spinal cord damage. A jaw thrust, not head-tilt, is used to open the airway in trauma.', 'Respiratory', '🫁'),
(104, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'A ventilated patient is likely ready for a weaning trial when:', '["The cause has improved, FiO2 is 0.4 or less with PEEP of 5–8, the patient is haemodynamically stable and awake", "The patient needs high-dose vasopressors", "FiO2 is 0.9 with PEEP of 15", "The patient is deeply sedated and paralysed"]'::jsonb, 0, 'Weaning criteria include adequate oxygenation, a stable circulation, a respiratory drive, the ability to cough and a rapid shallow breathing index below 105.', 'Respiratory', '🫁'),
(105, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'A ventilated patient suddenly desaturates and the cause is not clear. The first action is to:', '["Increase sedation", "Disconnect the ventilator and hand-ventilate with 100% oxygen", "Silence the alarms and call the doctor later", "Reduce the FiO2"]'::jsonb, 1, 'This separates a patient problem from a machine problem. Then work through DOPE: Displacement, Obstruction, Pneumothorax, Equipment failure.', 'Respiratory', '🫁'),
(106, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'At the end of anaesthesia with nitrous oxide, 100% oxygen is given for a few minutes to prevent:', '["Diffusion hypoxia", "Malignant hyperthermia", "Hypercalcaemia", "Bronchospasm"]'::jsonb, 0, 'Nitrous oxide floods out of the blood into the alveoli and dilutes the oxygen there.', 'Respiratory', '🫁'),
(107, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'During anaesthesia, a patient develops a rapidly rising temperature, muscle rigidity, tachycardia and a rising ETCO2. The specific drug treatment is:', '["Atropine", "Dantrolene", "Neostigmine", "Naloxone"]'::jsonb, 1, 'This is malignant hyperthermia, triggered by volatile agents or suxamethonium. Stop the trigger, give dantrolene, cool the patient and treat hyperkalaemia.', 'Respiratory', '🫁'),
(108, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'Mendelson''s syndrome is:', '["Chemical pneumonitis from aspirating acidic gastric contents during anaesthesia", "Pneumonia caused by Mycoplasma", "An allergic reaction to anaesthetic gases", "Collapse of the lung after a chest drain is removed"]'::jsonb, 0, 'Prevention: fasting, antacids or H2 blockers before surgery (especially in obstetrics), and rapid sequence induction with cricoid pressure.', 'Respiratory', '🫁'),
(109, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'Oxygen toxicity becomes a risk when a patient receives:', '["28% oxygen for 2 hours", "Room air for a week", "2 L/min by nasal cannula overnight", "FiO2 above 0.6 for more than about 24 hours"]'::jsonb, 3, 'High concentrations cause absorption atelectasis and lung injury, and retinopathy of prematurity in neonates. Use the lowest FiO2 that meets the SpO2 target.', 'Respiratory', '🫁'),
(110, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'After resuscitation from cardiac arrest, targeted temperature management keeps the core temperature at:', '["25–28°C", "37.5–38.5°C", "Below 30°C", "32–36°C, avoiding fever"]'::jsonb, 3, 'Controlled temperature and avoiding fever protect the brain from reperfusion injury. Watch for shivering, arrhythmias, electrolyte shifts and infection.', 'Respiratory', '🫁'),
(111, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'Which group of signs suggests hypercarbia (CO2 retention) rather than simple hypoxia?', '["Warm flushed skin, bounding pulse, headache, drowsiness and flapping tremor", "Cold clammy skin with central cyanosis only", "Bradycardia with pinpoint pupils", "Itching and urticaria"]'::jsonb, 0, 'CO2 is a vasodilator and a central nervous system depressant. Hypoxia causes restlessness, tachycardia and cyanosis, and only later bradycardia.', 'Respiratory', '🫁'),
(112, 'Anaesthesia & Mechanical Ventilation (CCN 415)', 'A monitored patient in cardiac arrest is in asystole. Correct management is:', '["Immediate defibrillation at 200 J", "Continuous CPR and adrenaline 1 mg IV every 3–5 minutes; do not defibrillate", "Synchronised cardioversion", "Atropine 3 mg and wait"]'::jsonb, 1, 'Asystole and PEA are non-shockable rhythms. Search for and treat the reversible causes (4 Hs and 4 Ts).', 'Respiratory', '🫁'),
(113, 'Medical-Surgical Emergencies I & II', 'The qSOFA criteria used to identify adults with suspected sepsis at risk of poor outcome are:', '["Temperature above 38°C, WBC above 12 and heart rate above 90", "Rash, fever and neck stiffness", "Respiratory rate 22/min or more, altered mental state and systolic BP 100 mmHg or less", "Urine output above 1 ml/kg/hr, normal BP and GCS 15"]'::jsonb, 2, 'Two or more qSOFA points outside the ICU suggests a higher risk of death. The older SIRS criteria (temperature, WBC, heart rate) are less specific.', 'Shock & Haemorrhage', '⚡'),
(114, 'Medical-Surgical Emergencies I & II', 'In septic shock with hypotension or lactate of 4 mmol/L or more, the initial fluid resuscitation is:', '["500 ml of 5% dextrose over 24 hours", "30 ml/kg of IV crystalloid in the first 3 hours", "Fluid restriction to 1 L/day", "Blood transfusion for every patient"]'::jsonb, 1, 'Give the fluid with early antibiotics (within 1 hour) and blood cultures, then a vasopressor if MAP stays below 65 mmHg.', 'Shock & Haemorrhage', '⚡'),
(115, 'Medical-Surgical Emergencies I & II', 'Multiple organ dysfunction syndrome (MODS) is:', '["Failure of one organ only", "A chronic illness lasting years", "Progressive dysfunction of two or more organ systems in an acutely ill patient, needing intervention to maintain homeostasis", "A normal response to surgery"]'::jsonb, 2, 'MODS often follows sepsis, shock or major trauma, and mortality rises with each organ that fails.', 'Shock & Haemorrhage', '⚡'),
(116, 'Medical-Surgical Emergencies I & II', 'In a haemodynamically unstable patient with a suspected open-book pelvic fracture, the immediate measure is:', '["Log-rolling the patient repeatedly to examine the back", "A pelvic binder at the level of the greater trochanters", "Springing the pelvis to confirm the fracture", "Inserting a urethral catheter first"]'::jsonb, 1, 'Pelvic fractures can bleed massively. Binding closes the pelvic volume and reduces bleeding until definitive control.', 'Shock & Haemorrhage', '⚡'),
(117, 'Medical-Surgical Emergencies I & II', 'After pelvic trauma, blood is seen at the urethral meatus. The nurse should:', '["Insert a large urethral catheter at once", "Ask the patient to void forcefully", "Not insert a urethral catheter until a urethrogram excludes urethral injury", "Insert a catheter only if the patient is in pain"]'::jsonb, 2, 'Catheterising through a torn urethra can turn a partial tear into a complete one. A suprapubic catheter may be needed.', 'Shock & Haemorrhage', '⚡'),
(118, 'Medical-Surgical Emergencies I & II', 'After a TURP with continuous bladder irrigation, a patient becomes confused and nauseated, with bradycardia, hypertension and a low serum sodium. This is:', '["TURP syndrome from absorption of the irrigating fluid", "Normal post-anaesthetic recovery", "Septic shock", "Hyperkalaemia"]'::jsonb, 0, 'Large volumes of hypotonic irrigation fluid absorbed through open prostatic veins cause fluid overload and dilutional hyponatraemia.', 'Shock & Haemorrhage', '⚡'),
(119, 'Medical-Surgical Emergencies I & II', 'A burns patient rescued from a closed room has singed nasal hair, soot in the mouth, carbonaceous sputum and a hoarse voice. The priority is:', '["Dressing the burns first", "Calculating the Parkland formula first", "Early assessment of the airway and intubation before oedema develops", "Giving oral fluids"]'::jsonb, 2, 'These are signs of inhalation injury. Airway swelling can progress quickly and make intubation impossible later.', 'Shock & Haemorrhage', '⚡'),
(120, 'Medical-Surgical Emergencies I & II', 'Intact skin with a non-blanchable red area over the sacrum is a:', '["Stage 2 pressure ulcer", "Stage 3 pressure ulcer", "Normal finding that needs no action", "Stage 1 pressure ulcer"]'::jsonb, 3, 'Stage 1 is the earliest sign of pressure damage. Relieve pressure, reposition and assess risk with a tool such as the Braden scale.', 'Shock & Haemorrhage', '⚡'),
(121, 'Medical-Surgical Emergencies I & II', 'According to Hans Selye, the three stages of the General Adaptation Syndrome (GAS) are:', '["Denial, anger and acceptance", "Alarm, resistance and exhaustion", "Shock, recovery and discharge", "Assessment, planning and evaluation"]'::jsonb, 1, 'GAS describes the body''s response to prolonged stress. Families and patients in the ICU can reach exhaustion without support.', 'Shock & Haemorrhage', '⚡'),
(122, 'Medical-Surgical Emergencies I & II', 'The cosyntropin (synthetic ACTH) stimulation test is used to diagnose:', '["Diabetes insipidus", "Hyperthyroidism", "Phaeochromocytoma", "Adrenal insufficiency"]'::jsonb, 3, 'If serum cortisol does not rise adequately after cosyntropin, the adrenal glands are not responding. This matters in septic shock that does not respond to vasopressors.', 'Shock & Haemorrhage', '⚡'),
(123, 'Medical-Surgical Emergencies I & II', 'Intra-abdominal pressure is usually measured:', '["Through a nasogastric tube with the patient sitting up", "With a sphygmomanometer cuff around the abdomen", "Through a peripheral IV cannula", "Through a urinary catheter, with about 25 ml of saline instilled, supine and at end-expiration"]'::jsonb, 3, 'The transducer is zeroed at the iliac crest in the mid-axillary line. Normal is about 5–7 mmHg. Abdominal compartment syndrome is above 20 mmHg with new organ dysfunction.', 'Shock & Haemorrhage', '⚡'),
(124, 'Medical-Surgical Emergencies I & II', 'Stress ulcer prophylaxis in high-risk ventilated ICU patients commonly uses:', '["Aspirin", "Ibuprofen", "A proton pump inhibitor such as pantoprazole, plus early enteral feeding", "High-dose steroids"]'::jsonb, 2, 'Shock, ventilation over 48 hours and coagulopathy raise the risk of stress ulcer bleeding. NSAIDs and steroids increase that risk.', 'Shock & Haemorrhage', '⚡'),
(125, 'Medical-Surgical Emergencies I & II', 'In acute pancreatitis, bluish discolouration around the umbilicus is called:', '["Grey Turner''s sign", "Murphy''s sign", "Cullen''s sign", "Rovsing''s sign"]'::jsonb, 2, 'Cullen''s sign (around the umbilicus) and Grey Turner''s sign (in the flanks) indicate retroperitoneal bleeding in severe haemorrhagic pancreatitis.', 'Shock & Haemorrhage', '⚡'),
(126, 'Medical-Surgical Emergencies I & II', 'An early warning feature of necrotising fasciitis is:', '["Severe pain out of proportion to the visible skin changes", "A painless, slowly growing lump", "Itching without pain", "Healing within 24 hours with oral antibiotics"]'::jsonb, 0, 'Infection spreads quickly along the fascial planes. Urgent surgical debridement plus broad-spectrum IV antibiotics saves lives.', 'Shock & Haemorrhage', '⚡'),
(127, 'Medical-Surgical Emergencies I & II', 'The ''golden hour'' of trauma refers to:', '["The first 60 minutes after injury, when rapid treatment most improves survival", "The first hour after hospital discharge", "Visiting hours in the ICU", "The hour before surgery when the patient fasts"]'::jsonb, 0, 'Most preventable trauma deaths come from airway problems, bleeding and tension pneumothorax, which must be treated early.', 'Shock & Haemorrhage', '⚡'),
(128, 'Medical-Surgical Emergencies I & II', 'A patient with severe accidental hypothermia (core temperature below 28°C) must be handled gently because:', '["They will wake up suddenly", "Their skin heals faster when moved", "Movement raises their temperature too quickly", "Rough movement can trigger ventricular fibrillation"]'::jsonb, 3, 'The cold myocardium is very irritable. Use active core rewarming, and remember: ''not dead until warm and dead''.', 'Shock & Haemorrhage', '⚡'),
(129, 'Medical-Surgical Emergencies I & II', 'In an under-water seal chest drain, continuous bubbling in the water-seal chamber indicates:', '["Normal function after the lung has re-expanded", "An air leak from the lung or the system", "A blocked drain", "Bleeding into the pleura"]'::jsonb, 1, 'Check the connections first, then report a persistent leak. Keep the bottle below chest level and do not clamp the drain routinely.', 'Shock & Haemorrhage', '⚡'),
(130, 'Medical-Surgical Emergencies I & II', 'A component of the ventilator-associated pneumonia (VAP) prevention bundle is:', '["Lying the patient flat", "Changing the ventilator circuit every 6 hours", "Deep sedation for every patient", "Raising the head of the bed to 30–45° with daily sedation holds"]'::jsonb, 3, 'The bundle also includes oral care, subglottic suction, cuff pressure checks, DVT and stress ulcer prophylaxis, and daily assessment for extubation.', 'Shock & Haemorrhage', '⚡'),
(131, 'Obstetrics & Gynaecology (CCN 423)', 'A woman with 7 weeks'' amenorrhoea collapses with lower abdominal pain, shoulder-tip pain, pallor and hypotension. The most likely diagnosis is:', '["Threatened miscarriage", "Hyperemesis gravidarum", "Ruptured ectopic pregnancy", "Urinary tract infection"]'::jsonb, 2, 'Intraperitoneal blood irritates the diaphragm (shoulder-tip pain). This is a surgical emergency: resuscitate and arrange theatre at once.', 'Obstetric & Neonatal', '🤱'),
(132, 'Obstetrics & Gynaecology (CCN 423)', 'Painless, bright red vaginal bleeding in the third trimester with a soft, non-tender uterus suggests:', '["Placental abruption", "Placenta praevia", "Uterine rupture", "Vasa praevia with a tense uterus"]'::jsonb, 1, 'Abruption causes painful bleeding with a hard, tender (''woody'') uterus and fetal distress. In praevia, a vaginal examination must NOT be done.', 'Obstetric & Neonatal', '🤱'),
(133, 'Obstetrics & Gynaecology (CCN 423)', 'Premature rupture of membranes (PROM) means rupture of the membranes:', '["During the second stage of labour", "Before the onset of labour", "After delivery of the baby", "Only after 42 weeks"]'::jsonb, 1, 'Preterm PROM happens before 37 weeks. The main risks are chorioamnionitis, cord prolapse and preterm birth.', 'Obstetric & Neonatal', '🤱'),
(134, 'Obstetrics & Gynaecology (CCN 423)', 'Cervical incompetence is commonly managed with:', '["Hysterectomy", "Oxytocin infusion", "Bed rest alone, with no follow-up", "Cervical cerclage (for example, a McDonald suture)"]'::jsonb, 3, 'A purse-string stitch supports the weak cervix and is removed at about 37 weeks or if labour starts.', 'Obstetric & Neonatal', '🤱'),
(135, 'Obstetrics & Gynaecology (CCN 423)', 'Anti-D immunoglobulin for a Rhesus-negative mother with a Rhesus-positive baby should be given within:', '["7 days of delivery", "1 month of delivery", "72 hours of delivery", "The next pregnancy only"]'::jsonb, 2, 'Anti-D destroys fetal Rh-positive cells before the mother makes her own antibodies, which prevents haemolytic disease in the next baby.', 'Obstetric & Neonatal', '🤱'),
(136, 'Obstetrics & Gynaecology (CCN 423)', 'Puerperal sepsis is infection of the genital tract occurring:', '["Only during pregnancy", "Only in the first 24 hours after delivery", "More than 6 months after delivery", "Between rupture of membranes or labour and 42 days after delivery"]'::jsonb, 3, 'Common causes are Group A Streptococcus, E. coli and anaerobes. Watch for fever, foul lochia, uterine tenderness and signs of shock.', 'Obstetric & Neonatal', '🤱'),
(137, 'Obstetrics & Gynaecology (CCN 423)', 'During CPR on a woman more than 20 weeks pregnant, the uterus should be displaced manually to the LEFT to:', '["Relieve compression of the inferior vena cava and improve venous return", "Make chest compressions easier", "Reduce the risk of PPH", "Protect the baby from the defibrillator"]'::jsonb, 0, 'Aortocaval compression greatly reduces cardiac output. Perimortem caesarean section is considered if there is no ROSC within about 4 minutes.', 'Obstetric & Neonatal', '🤱'),
(138, 'Obstetrics & Gynaecology (CCN 423)', 'Polyhydramnios is associated with:', '["Fetal renal agenesis", "Post-term pregnancy only", "Maternal diabetes and fetal oesophageal atresia", "Fetal growth restriction from placental insufficiency"]'::jsonb, 2, 'A fetus that cannot swallow, or one producing too much urine (diabetes), causes excess amniotic fluid. Renal agenesis causes oligohydramnios.', 'Obstetric & Neonatal', '🤱'),
(139, 'Obstetrics & Gynaecology (CCN 423)', 'A danger of untreated hyperemesis gravidarum, especially if glucose is given without thiamine, is:', '["Placenta praevia", "Polycythaemia", "Hypercalcaemia", "Wernicke''s encephalopathy"]'::jsonb, 3, 'Persistent vomiting depletes thiamine. Give thiamine along with IV fluids, antiemetics and electrolyte replacement.', 'Obstetric & Neonatal', '🤱'),
(140, 'Neonatology & Paediatrics (CCN 422)', 'The compression-to-ventilation ratio for neonatal resuscitation is:', '["30:2", "15:2", "5:1", "3:1"]'::jsonb, 3, 'In newborns, 90 compressions and 30 breaths a minute are given, because most neonatal arrests are caused by asphyxia.', 'Obstetric & Neonatal', '🤱'),
(141, 'Neonatology & Paediatrics (CCN 422)', 'Neonatal jaundice is considered PATHOLOGICAL if it:', '["Appears within the first 24 hours of life", "Appears on day 3 in a term baby who is feeding well", "Fades by day 10", "Affects only the face"]'::jsonb, 0, 'Early jaundice suggests haemolysis (Rh or ABO incompatibility, G6PD deficiency) or sepsis. High unconjugated bilirubin can cause kernicterus, so treat with phototherapy or exchange transfusion.', 'Obstetric & Neonatal', '🤱'),
(142, 'Neonatology & Paediatrics (CCN 422)', 'A 5-week-old boy has projectile non-bilious vomiting after feeds and a palpable ''olive'' mass in the abdomen. The diagnosis is:', '["Intussusception", "Hirschsprung''s disease", "Congenital hypertrophic pyloric stenosis", "Duodenal atresia"]'::jsonb, 2, 'Vomiting causes hypochloraemic, hypokalaemic metabolic alkalosis, which must be corrected before pyloromyotomy.', 'Obstetric & Neonatal', '🤱'),
(143, 'Neonatology & Paediatrics (CCN 422)', 'A 9-month-old has episodes of screaming with drawing up of the legs and passes ''red currant jelly'' stools. The likely diagnosis is:', '["Intussusception", "Pyloric stenosis", "Gastroenteritis", "Appendicitis"]'::jsonb, 0, 'One segment of bowel telescopes into another (usually ileocolic). A sausage-shaped mass may be felt. It is treated by air or contrast enema reduction or surgery.', 'Obstetric & Neonatal', '🤱'),
(144, 'Neonatology & Paediatrics (CCN 422)', 'A newborn fails to pass meconium within 48 hours and has abdominal distension. Rectal biopsy shows no ganglion cells. The diagnosis is:', '["Meconium aspiration", "Pyloric stenosis", "Hirschsprung''s disease", "Intussusception"]'::jsonb, 2, 'In Hirschsprung''s disease (aganglionic megacolon), the affected segment cannot relax. Enterocolitis is a dangerous complication.', 'Obstetric & Neonatal', '🤱'),
(145, 'Neonatology & Paediatrics (CCN 422)', 'A newborn has excessive frothy saliva, chokes and turns cyanosed with the first feed, and a nasogastric tube cannot be passed. The likely diagnosis is:', '["Oesophageal atresia with tracheo-oesophageal fistula", "Pyloric stenosis", "Cleft lip only", "Normal newborn behaviour"]'::jsonb, 0, 'Stop oral feeds, nurse head-up, give continuous suction of the upper pouch (Replogle tube) and arrange surgery.', 'Obstetric & Neonatal', '🤱'),
(146, 'Neonatology & Paediatrics (CCN 422)', 'A child with SEVERE dehydration (lethargic, sunken eyes, skin pinch going back very slowly, unable to drink) should receive:', '["Oral rehydration solution only at home (Plan A)", "IV Ringer''s lactate or normal saline, 100 ml/kg (WHO Plan C)", "Plain water by mouth", "No fluids until the stool is cultured"]'::jsonb, 1, 'Plan C gives 100 ml/kg IV: under 12 months, 30 ml/kg in 1 hour then 70 ml/kg in 5 hours; older children over 30 minutes then 2½ hours.', 'Obstetric & Neonatal', '🤱'),
(147, 'Neonatology & Paediatrics (CCN 422)', 'A child presents with high fever, drooling, a muffled voice and sits leaning forward (tripod position). The nurse should NOT:', '["Examine the throat with a tongue depressor", "Keep the child calm on the parent''s lap", "Call for an anaesthetist or ENT surgeon", "Give oxygen without upsetting the child"]'::jsonb, 0, 'This suggests epiglottitis. Examining the throat can cause complete airway obstruction. Croup, by contrast, presents with a barking cough and stridor.', 'Obstetric & Neonatal', '🤱'),
(148, 'Neonatology & Paediatrics (CCN 422)', 'Simple febrile convulsions in children typically:', '["Occur between 6 months and 5 years, are generalised and last under 15 minutes", "Occur only in teenagers", "Always lead to epilepsy", "Last more than 30 minutes"]'::jsonb, 0, 'Manage the airway, cool the child and treat the cause of the fever. Give a benzodiazepine if the seizure lasts more than 5 minutes.', 'Obstetric & Neonatal', '🤱'),
(149, 'Neonatology & Paediatrics (CCN 422)', 'Lassa fever is transmitted mainly by:', '["Mosquito bites", "The multimammate rat (Mastomys natalensis), through contaminated food or urine", "Tsetse flies", "Contaminated water containing Vibrio cholerae"]'::jsonb, 1, 'Person-to-person spread through body fluids also occurs, so barrier nursing is essential. Ribavirin is the antiviral used.', 'Obstetric & Neonatal', '🤱'),
(150, 'Neonatology & Paediatrics (CCN 422)', 'The key advice to reduce the risk of Sudden Infant Death Syndrome (SIDS) is to:', '["Place the baby face down to sleep", "Place the baby on the back to sleep, on a firm flat surface, in a smoke-free environment", "Use soft pillows and heavy blankets", "Let the baby sleep on a sofa with a parent"]'::jsonb, 1, '''Back to sleep'' campaigns have greatly reduced SIDS. Avoid overheating and smoking, and avoid bed-sharing after alcohol or drugs.', 'Obstetric & Neonatal', '🤱'),
(151, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'Florence Nightingale''s theory of nursing focuses mainly on:', '["Self-care deficits", "Adaptation to stimuli", "The environment: fresh air, light, warmth, cleanliness and quiet", "Fourteen basic needs"]'::jsonb, 2, 'Nightingale''s environmental theory holds that manipulating the environment helps the body heal itself.', 'Research & Nursing Process', '📊'),
(152, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'The nurse theorist who described 14 basic needs and defined nursing as helping the person do what they would do unaided if they had the strength, will or knowledge is:', '["Dorothea Orem", "Sister Callista Roy", "Betty Neuman", "Virginia Henderson"]'::jsonb, 3, 'Henderson''s definition aims to make the patient independent as quickly as possible.', 'Research & Nursing Process', '📊'),
(153, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'Using Orem''s model, an unconscious, ventilated ICU patient needs which nursing system?', '["Wholly compensatory", "Partly compensatory", "Supportive-educative", "Self-care agency"]'::jsonb, 0, 'The nurse does everything for a patient who cannot take part in self-care. As the patient improves, care moves to partly compensatory, then supportive-educative.', 'Research & Nursing Process', '📊'),
(154, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'Sister Callista Roy''s model views the person as:', '["A set of 14 basic needs", "An energy field that cannot be divided", "A self-care agent", "An adaptive system responding to focal, contextual and residual stimuli"]'::jsonb, 3, 'Roy''s four adaptive modes are physiological, self-concept, role function and interdependence.', 'Research & Nursing Process', '📊'),
(155, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'In Betty Neuman''s systems model, the client is protected from stressors by:', '["Fourteen activities of daily living", "Lines of defence and resistance around a basic core", "Self-care requisites", "Three nursing systems"]'::jsonb, 1, 'Nursing is prevention as intervention: primary, secondary and tertiary, aimed at keeping the system stable.', 'Research & Nursing Process', '📊'),
(156, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'The theorist who described the person as an irreducible energy field (the Science of Unitary Human Beings) is:', '["Florence Nightingale", "Marjory Gordon", "Martha Rogers", "Abraham Maslow"]'::jsonb, 2, 'Rogers saw the person and the environment as continuous, interacting energy fields.', 'Research & Nursing Process', '📊'),
(157, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'Marjory Gordon organised nursing assessment data into:', '["5 levels of need", "4 adaptive modes", "3 nursing systems", "11 functional health patterns"]'::jsonb, 3, 'Examples include health perception and management, nutrition and metabolism, elimination, and activity and exercise. They give a structure for the nursing database.', 'Research & Nursing Process', '📊'),
(158, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'Using Maslow''s hierarchy, which need does the ICU nurse meet FIRST?', '["Self-esteem", "Love and belonging", "Self-actualisation", "Airway and breathing (physiological needs)"]'::jsonb, 3, 'Lower-level physiological needs must be met before higher needs. Airway, breathing and circulation come first.', 'Research & Nursing Process', '📊'),
(159, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'A complete NANDA-I actual nursing diagnosis is written in the PES format, which stands for:', '["Plan, Evaluate, Summarise", "Patient, Environment, Staff", "Problem, Etiology (related factors), Signs and symptoms", "Priority, Expected outcome, Solution"]'::jsonb, 2, 'Example: Ineffective airway clearance (P) related to thick secretions (E), as shown by coarse crackles and an ineffective cough (S).', 'Research & Nursing Process', '📊'),
(160, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'The standardised nursing language used to describe and measure PATIENT OUTCOMES is:', '["Nursing Interventions Classification (NIC)", "NANDA-I", "ICD-10", "Nursing Outcomes Classification (NOC)"]'::jsonb, 3, 'NANDA names the diagnosis, NIC names the intervention and NOC names the measurable outcome.', 'Research & Nursing Process', '📊'),
(161, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'A goal written in the SMART format must be:', '["Specific, Measurable, Achievable, Realistic and Time-bound", "Simple, Moderate, Accurate, Rapid and Tested", "Standard, Medical, Approved, Recorded and Typed", "Short, Meaningful, Agreed, Reviewed and Total"]'::jsonb, 0, 'Example: ''The patient will maintain SpO2 of 94% or more on 2 L oxygen by 0800 hours tomorrow.''', 'Research & Nursing Process', '📊'),
(162, 'Principles & Practice of CCN: Theories, Nursing Process & QA (CCN 413)', 'A nursing audit carried out by reviewing the charts of patients after they have been discharged is called:', '["Concurrent audit", "Retrospective audit", "Prospective audit", "Peer appraisal"]'::jsonb, 1, 'Concurrent audit happens while the patient is still receiving care. Both are tools of quality assurance.', 'Research & Nursing Process', '📊'),
(163, 'Applied Research Methodology & Statistics (CCN 416)', 'The hypothesis which states that there is NO relationship or difference between the variables is the:', '["Null hypothesis", "Research (alternative) hypothesis", "Directional hypothesis", "Complex hypothesis"]'::jsonb, 0, 'Statistical tests are designed to reject or fail to reject the null hypothesis (H0).', 'Research & Nursing Process', '📊'),
(164, 'Applied Research Methodology & Statistics (CCN 416)', 'In a study of the effect of chest physiotherapy on oxygen saturation, oxygen saturation is the:', '["Dependent variable", "Independent variable", "Extraneous variable", "Demographic variable"]'::jsonb, 0, 'The independent variable (chest physiotherapy) is the presumed cause. The dependent variable (SpO2) is the measured outcome.', 'Research & Nursing Process', '📊'),
(165, 'Applied Research Methodology & Statistics (CCN 416)', 'A sampling method in which every member of the population has an equal chance of being selected is:', '["Convenience sampling", "Simple random sampling", "Purposive sampling", "Snowball sampling"]'::jsonb, 1, 'Probability sampling (simple random, stratified, systematic, cluster) reduces bias. Convenience, purposive and snowball sampling are non-probability methods.', 'Research & Nursing Process', '📊'),
(166, 'Applied Research Methodology & Statistics (CCN 416)', 'Grading pain as mild, moderate or severe is an example of which scale of measurement?', '["Ordinal", "Nominal", "Interval", "Ratio"]'::jsonb, 0, 'Ordinal data have a rank order but unequal gaps. Nominal data are categories only (such as gender). Ratio data have a true zero (such as weight).', 'Research & Nursing Process', '📊'),
(167, 'Applied Research Methodology & Statistics (CCN 416)', 'The ages of five ICU nurses are 24, 27, 27, 31 and 41 years. The mode is:', '["27", "30", "31", "17"]'::jsonb, 0, 'The mode is the most frequent value (27). The mean is 30 and the median (middle value) is also 27. The range is 41 − 24 = 17.', 'Research & Nursing Process', '📊'),
(168, 'Applied Research Methodology & Statistics (CCN 416)', 'The statistic that shows how widely values are spread around the mean is the:', '["Mode", "Median", "Sample size", "Standard deviation"]'::jsonb, 3, 'A small standard deviation means values cluster close to the mean. A large one means they are widely spread.', 'Research & Nursing Process', '📊'),
(169, 'Applied Research Methodology & Statistics (CCN 416)', 'In nursing research, a result is usually reported as statistically significant when:', '["p < 0.05", "p > 0.5", "p = 1.0", "The sample size is above 1,000"]'::jsonb, 0, 'p < 0.05 means a result this extreme would occur by chance less than 5% of the time if the null hypothesis were true.', 'Research & Nursing Process', '📊'),
(170, 'Applied Research Methodology & Statistics (CCN 416)', 'The appropriate inferential test for an association between two categorical (nominal) variables, such as gender and smoking status, is the:', '["Pearson correlation", "Student''s t-test", "Analysis of variance (ANOVA)", "Chi-square test"]'::jsonb, 3, 'Chi-square compares observed and expected frequencies. T-tests and ANOVA compare means of continuous data.', 'Research & Nursing Process', '📊'),
(171, 'Applied Research Methodology & Statistics (CCN 416)', 'The three features of a true experimental design are:', '["Observation, description and interview", "Survey, questionnaire and checklist", "Case study, history and narrative", "Manipulation, control and randomisation"]'::jsonb, 3, 'Without random assignment, a study is quasi-experimental.', 'Research & Nursing Process', '📊'),
(172, 'Applied Research Methodology & Statistics (CCN 416)', 'A small-scale trial of a study done before the main study, to test the instrument and procedures, is a:', '["Pilot study", "Literature review", "Meta-analysis", "Longitudinal study"]'::jsonb, 0, 'A pilot study finds problems with the questionnaire, timing or logistics before resources are committed to the main study.', 'Research & Nursing Process', '📊'),
(173, 'Applied Research Methodology & Statistics (CCN 416)', 'The consistency of a research instrument, giving the same results when used repeatedly under the same conditions, is its:', '["Validity", "Generalisability", "Reliability", "Sensitivity"]'::jsonb, 2, 'Validity is whether the instrument measures what it is supposed to measure. An instrument can be reliable without being valid.', 'Research & Nursing Process', '📊'),
(174, 'Principles of Management & Teaching (GST 420)', 'A new ICU manager decides the unit''s objectives for the year and how to achieve them. This management function is:', '["Controlling", "Directing", "Planning", "Staffing"]'::jsonb, 2, 'Gulick''s POSDCORB: Planning, Organising, Staffing, Directing, Co-ordinating, Reporting and Budgeting. Planning sets the goals the other functions work towards.', 'Ethics, Law & Management', '⚖️'),
(175, 'Principles of Management & Teaching (GST 420)', 'Henri Fayol''s principle that each employee should receive orders from only one superior is called:', '["Span of control", "Unity of command", "Division of labour", "Esprit de corps"]'::jsonb, 1, 'Unity of command prevents confusion and conflicting instructions. Span of control is the number of staff one manager supervises.', 'Ethics, Law & Management', '⚖️'),
(176, 'Principles of Management & Teaching (GST 420)', 'The ''father of scientific management'', who used time-and-motion studies to improve efficiency, is:', '["Elton Mayo", "Douglas McGregor", "Frederick Taylor", "Abraham Maslow"]'::jsonb, 2, 'Elton Mayo''s Hawthorne studies began the human relations school. McGregor described Theory X and Theory Y.', 'Ethics, Law & Management', '⚖️'),
(177, 'Principles of Management & Teaching (GST 420)', 'According to Herzberg''s two-factor theory, salary, working conditions and supervision are:', '["Motivators", "Self-actualisation needs", "Hygiene (maintenance) factors", "Theory Y assumptions"]'::jsonb, 2, 'Hygiene factors prevent dissatisfaction but do not motivate. Achievement, recognition, responsibility and growth are the true motivators.', 'Ethics, Law & Management', '⚖️'),
(178, 'Principles of Management & Teaching (GST 420)', 'During a cardiac arrest in the ICU, the most effective leadership style is:', '["Laissez-faire", "Autocratic (directive)", "Democratic, with a vote on each step", "Absent leadership"]'::jsonb, 1, 'In emergencies, clear, quick commands from one leader save time. Democratic leadership suits planning and non-urgent decisions.', 'Ethics, Law & Management', '⚖️'),
(179, 'Principles of Management & Teaching (GST 420)', 'When a ward manager delegates a task to a nurse:', '["The manager is no longer accountable", "Authority is never transferred", "The nurse may refuse without reason", "Responsibility is transferred but the manager remains accountable"]'::jsonb, 3, 'Delegate the right task to the right person, with the right communication and supervision.', 'Ethics, Law & Management', '⚖️'),
(180, 'Principles of Management & Teaching (GST 420)', 'In budgeting, money for buying a new ICU ventilator that will last many years is part of the:', '["Operating budget", "Personnel budget", "Petty cash", "Capital budget"]'::jsonb, 3, 'The capital budget covers major long-life equipment and buildings. The operating budget covers day-to-day running costs.', 'Ethics, Law & Management', '⚖️'),
(181, 'Principles of Management & Teaching (GST 420)', 'Malcolm Knowles'' theory of adult learning (andragogy) states that adults learn best when:', '["They are passive listeners only", "Learning is self-directed, problem-centred and builds on their experience", "Content has no link to their work", "They are taught exactly like children"]'::jsonb, 1, 'Adults are motivated by immediate relevance. Use case studies, discussion and practice.', 'Ethics, Law & Management', '⚖️'),
(182, 'Principles of Management & Teaching (GST 420)', 'The most suitable teaching method for a psychomotor skill such as tracheal suctioning is:', '["Lecture only", "Demonstration followed by return demonstration", "Reading a handout only", "Group debate"]'::jsonb, 1, 'Skills are learnt by watching and then doing under supervision, with feedback. This is Bloom''s psychomotor domain.', 'Ethics, Law & Management', '⚖️'),
(183, 'Principles of Management & Teaching (GST 420)', 'Evaluation carried out during a teaching programme, to improve it while it is still running, is:', '["Formative evaluation", "Summative evaluation", "Retrospective evaluation", "Terminal evaluation"]'::jsonb, 0, 'Summative evaluation judges the overall result at the end of the programme.', 'Ethics, Law & Management', '⚖️'),
(184, 'Principles of Management & Teaching (GST 420)', 'An incident report in risk management is mainly used to:', '["Punish the nurse involved", "Identify and correct system problems so that errors are prevented", "Replace the entry in the patient''s notes", "Inform the patient''s lawyer"]'::jsonb, 1, 'Incident reporting should be prompt, factual and non-punitive. The report is not filed in the patient''s chart, although the event and care given are documented there.', 'Ethics, Law & Management', '⚖️'),
(185, 'Ethico-Legal Issues in CCN (CCN 424)', 'The Nursing and Midwifery Council of Nigeria (NMCN) was established by:', '["Decree No. 1 of 1960", "The 1999 Constitution only", "The Public Health Act of 1917", "Decree No. 89 of 1979"]'::jsonb, 3, 'NMCN regulates nursing and midwifery education and practice in Nigeria. The decree is now an Act (Cap N143, Laws of the Federation 2004).', 'Ethics, Law & Management', '⚖️'),
(186, 'Ethico-Legal Issues in CCN (CCN 424)', 'A swab is found in a patient''s abdomen after surgery. The legal doctrine meaning ''the thing speaks for itself'' is:', '["Respondeat superior", "Locum tenens", "Res ipsa loquitur", "Habeas corpus"]'::jsonb, 2, 'The injury could not have happened without negligence, so the burden moves to the defendant. Respondeat superior makes the employer liable for staff acts.', 'Ethics, Law & Management', '⚖️'),
(187, 'Ethico-Legal Issues in CCN (CCN 424)', 'To prove negligence against a nurse, the four elements that must be shown are:', '["Duty of care, breach of that duty, causation and damage", "Intent, malice, motive and profit", "Consent, capacity, disclosure and voluntariness", "Assessment, diagnosis, planning and evaluation"]'::jsonb, 0, 'All four must be present. A breach that causes no harm is not actionable negligence.', 'Ethics, Law & Management', '⚖️'),
(188, 'Ethico-Legal Issues in CCN (CCN 424)', 'A nurse inserts a urinary catheter into a competent patient who has clearly refused it. This is:', '["Assault", "Defamation", "False imprisonment", "Battery"]'::jsonb, 3, 'Battery is unlawful touching without consent. Assault is a threat that makes the person fear harmful contact.', 'Ethics, Law & Management', '⚖️'),
(189, 'Ethico-Legal Issues in CCN (CCN 424)', 'An unconscious patient with no relatives present needs life-saving emergency surgery. Treatment can proceed under:', '["Implied consent in an emergency", "Written consent from the cleaner", "Consent from the hospital chaplain", "No treatment until the patient wakes"]'::jsonb, 0, 'The law presumes a reasonable person would consent to life-saving treatment. Document the emergency clearly.', 'Ethics, Law & Management', '⚖️'),
(190, 'Ethico-Legal Issues in CCN (CCN 424)', 'The ethical principle of telling the truth to patients is:', '["Fidelity", "Beneficence", "Veracity", "Justice"]'::jsonb, 2, 'Fidelity is keeping promises, beneficence is doing good and justice is fairness.', 'Ethics, Law & Management', '⚖️'),
(191, 'Ethico-Legal Issues in CCN (CCN 424)', 'When a patient has a valid Do-Not-Resuscitate (DNR) order, the nurse should:', '["Stop all nursing care", "Stop feeding and pain relief", "Ignore the order and perform CPR", "Withhold CPR in arrest but continue all other appropriate care and comfort"]'::jsonb, 3, 'DNR applies only to cardiopulmonary resuscitation. It does not mean ''do not treat'' or ''do not care''.', 'Ethics, Law & Management', '⚖️'),
(192, 'Ethico-Legal Issues in CCN (CCN 424)', 'A nurse stops at a road accident and gives first aid in good faith. Protection from liability (unless there is gross negligence) is provided by:', '["Res ipsa loquitur", "The Good Samaritan law", "Respondeat superior", "The Patient''s Bill of Rights"]'::jsonb, 1, 'The aid must be within the nurse''s competence, given without expectation of payment, and not grossly negligent.', 'Ethics, Law & Management', '⚖️'),
(193, 'Ethico-Legal Issues in CCN (CCN 424)', 'The correct way to correct an error in a patient''s handwritten record is to:', '["Use correction fluid", "Draw a single line through it, write ''error'', then initial, date and time it", "Tear out the page and rewrite", "Scribble over it so it cannot be read"]'::jsonb, 1, 'The original entry must stay readable. Altering records can look like a cover-up. Remember: ''not documented, not done''.', 'Ethics, Law & Management', '⚖️'),
(194, 'Ethico-Legal Issues in CCN (CCN 424)', 'A conscious, competent adult refuses a recommended blood transfusion. The nurse should:', '["Give the transfusion while the patient sleeps", "Restrain the patient and transfuse", "Respect the decision, make sure the patient understands the risks, and document the refusal (against medical advice)", "Discharge the patient without informing the doctor"]'::jsonb, 2, 'Autonomy gives a competent adult the right to refuse treatment. Inform the doctor and obtain a signed refusal form.', 'Ethics, Law & Management', '⚖️'),
(195, 'Applied Nutrition (CCN 417)', 'The Subjective Global Assessment (SGA) of nutrition is based on:', '["Serum albumin alone", "Body weight on admission only", "Patient history (weight change, intake, GI symptoms, function) and physical examination", "Chest X-ray findings"]'::jsonb, 2, 'SGA classifies patients as A (well nourished), B (moderately malnourished) or C (severely malnourished).', 'GI, Endocrine & Metabolic', '🍽️'),
(196, 'Applied Nutrition (CCN 417)', 'When a severely malnourished patient is fed, the electrolyte abnormality typical of refeeding syndrome is:', '["Hypernatraemia", "Hypophosphataemia", "Hypercalcaemia", "Hyperkalaemia"]'::jsonb, 1, 'Insulin released with feeding drives phosphate, potassium and magnesium into cells. Start feeds slowly, give thiamine and monitor electrolytes.', 'GI, Endocrine & Metabolic', '🍽️'),
(197, 'Applied Nutrition (CCN 417)', 'For a critically ill patient with a working gut, the preferred route of nutrition is:', '["Total parenteral nutrition", "Nil by mouth until discharge", "Enteral feeding, started early", "IV 5% dextrose only"]'::jsonb, 2, '''If the gut works, use it.'' Enteral nutrition keeps the gut barrier intact and has fewer infectious and metabolic complications than TPN.', 'GI, Endocrine & Metabolic', '🍽️'),
(198, 'Applied Nutrition (CCN 417)', 'Before giving a feed through a newly inserted nasogastric tube, correct position can be confirmed by:', '["Listening for a ''whoosh'' of air over the stomach", "An aspirate pH of 5.5 or less, or a chest X-ray", "Placing the tube end in water to look for bubbles", "Asking the patient to swallow"]'::jsonb, 1, 'The ''whoosh'' test and the bubble test are unreliable and no longer recommended. When pH testing is not possible, an X-ray is the gold standard.', 'GI, Endocrine & Metabolic', '🍽️'),
(199, 'Physiotherapy in Critical Care (CCN 425)', 'The main purpose of manual hyperinflation (bagging) in an intubated patient is to:', '["Lower the patient''s blood pressure", "Reduce oxygen delivery", "Re-expand collapsed alveoli and move secretions towards the larger airways", "Replace the need for suctioning"]'::jsonb, 2, 'A slow, deep breath, a pause, then a quick release imitates a cough. Use it with caution in unstable patients and with high PEEP.', 'Mixed Revision', '📚'),
(200, 'Physiotherapy in Critical Care (CCN 425)', 'Transcutaneous Electrical Nerve Stimulation (TENS) is used in critical care mainly for:', '["Pain relief", "Defibrillation", "Diagnosis of fractures", "Measuring oxygen saturation"]'::jsonb, 0, 'TENS sends low-voltage impulses through the skin and blocks pain signals (gate control theory). It is an adjunct that reduces the need for analgesics.', 'Mixed Revision', '📚')
) as v(n, topic, q, opts, ans_idx, exp, category, category_icon)
where not exists (
  select 1 from public.questions x where x.source = 'CCN Exam Room Mock — 200 Questions (Oct 2026)' and x.q = v.q
);

insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids,
                               show_answers, show_score, max_warnings, shuffle, all_candidates, attempts_allowed)
select 'CCN Council Mock Exam — 200 Questions',
       'This exam has 200 questions covering the full CCN curriculum. Choose the ONE best answer for each question. Each correct answer carries 1 mark. You have 200 minutes.',
       timestamptz '2026-10-23 08:00:00+01', timestamptz '2026-10-23 18:00:00+01', 200,
       (select array_agg(id order by id) from public.questions where source = 'CCN Exam Room Mock — 200 Questions (Oct 2026)'),
       false, true, 3, true, true, 1
where not exists (select 1 from public.exam_exams where title = 'CCN Council Mock Exam — 200 Questions');

-- Check: both numbers should be 200.
select (select count(*) from public.questions where source = 'CCN Exam Room Mock — 200 Questions (Oct 2026)') as questions_added,
       (select cardinality(question_ids) from public.exam_exams where title = 'CCN Council Mock Exam — 200 Questions') as questions_in_exam;
